import{_ as e,o as r,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"guides/supermarket.md","filePath":"guides/supermarket.md","lastUpdated":1792323081000}'),o={name:"guides/supermarket.md"};function s(i,t,l,p,d,h){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>The Supermarket is Memoh&#39;s built-in App catalog. An <strong>App</strong> here is a packaged unit of capability: one App can carry several <strong>Skills</strong> (reusable procedures), <strong>dependencies</strong> (tools installed into the workspace), and <strong>connectors</strong> (bindings to third-party services such as GitHub or Notion). You install the App as a whole — no separate hunting for Skills or connectors.</p><p>Open <strong>Supermarket</strong> from the client sidebar: Apps are laid out by category, searchable, and filterable by tag. An App&#39;s detail page shows its description, component makeup (how many Skills, dependencies, and connectors), author, version, source registry, and links.</p><hr><h2 id="install-an-app" tabindex="-1">Install an App <a class="header-anchor" href="#install-an-app" aria-label="Permalink to &quot;Install an App&quot;">​</a></h2><ol><li>Pick an App in the <strong>Supermarket</strong> and open its detail page.</li><li>Click <strong>Install to Bot</strong> and choose the target bot.</li><li>If the App declares environment variables, fill in the required values first.</li><li>Confirm the installation.</li></ol><p>Installing and updating needs the bot&#39;s workspace running: Skills are written into the workspace, dependencies are installed into it, and connectors are bound. Installation shows progress; an interrupted install can be <strong>resumed</strong> or <strong>restored</strong>.</p><hr><h2 id="after-installing-the-bot-s-apps-tab" tabindex="-1">After installing: the bot&#39;s Apps tab <a class="header-anchor" href="#after-installing-the-bot-s-apps-tab" aria-label="Permalink to &quot;After installing: the bot&#39;s Apps tab&quot;">​</a></h2><p>The <strong>Apps</strong> tab on the bot detail page lists installed Apps with per-component status:</p><table tabindex="0"><thead><tr><th>Component</th><th>Where it goes</th></tr></thead><tbody><tr><td><strong>Skills</strong></td><td>Written to the managed workspace directory <code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code>, owned by the App — updated and removed with it, so don&#39;t edit them by hand (see <a href="./skills.html">Skills</a>)</td></tr><tr><td><strong>Dependencies</strong></td><td>Installed into the bot&#39;s workspace and shared with other Apps in the same workspace that need them</td></tr><tr><td><strong>Connectors</strong></td><td>Marked <strong>Needs authorization</strong>, <strong>Optional</strong>, or <strong>Shared across workspaces</strong>; click <strong>Authorize</strong> to run OAuth or enter an API key (see <a href="./../self-hosted/connectors.html">Connectors</a>)</td></tr></tbody></table><p>Common actions: <strong>Check for updates</strong>, <strong>Update</strong>, <strong>Remove</strong>. When some components failed or still need authorization, the App is flagged as needing attention — open its component list to finish setup.</p><hr><h2 id="where-the-catalog-comes-from" tabindex="-1">Where the catalog comes from <a class="header-anchor" href="#where-the-catalog-comes-from" aria-label="Permalink to &quot;Where the catalog comes from&quot;">​</a></h2><p>Supermarket content is served from an upstream registry, <code>supermarket.memoh.ai</code> by default. Self-hosted instances can point <code>supermarket.base_url</code> at another trusted catalog; see the configuration reference in <a href="./../self-hosted/docker.html">Server Deploy</a>.</p><hr><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>New Apps can be submitted to:</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>',19)])])}const u=e(o,[["render",s]]);export{g as __pageData,u as default};
